for a in actions:
 a['effects']=[{'field':'rank','op':'add','value':1,'cap':10},{'field':'rankUpReady.observedValue','op':'set','value':None},{'field':'rankUpReady.observedRank','op':'set','value':None},{'field':'affinity','op':'set','value':None}]
 a['effectScope']='Fields are relative to the action entity socialLinks state; null means unknown, never zero'
(P/'observation_gated_rank_actions.json').write_text(json.dumps({'schemaVersion':1,'actions':actions,'coverage':'17 non-guaranteed manual links. This enables confirmed-ready next actions; it does not complete their long-horizon numerical model.'},ensure_ascii=False,indent=2)+'\n');print(len(actions),'observation-gated actions')
